preset_css:
/* Web 1.0 Inject */
* { border-radius: 0 !important; box-shadow: none !important; }
.mor-post, .runelite-panel, .main-header, .mor-footer { border-style: ridge; border-width: 3px; border-color: var(--border-color); }
.main-header { background: linear-gradient(90deg, #000080 0%, #1084d0 100%) !important; color: #ffffff !important; border-bottom: 2px solid #000040; }
.main-header .institute-title, .main-header .mor-nav a { color: #ffffff !important; font-family: 'MS Sans Serif', Tahoma, sans-serif; }
button, .pager-btn { border-style: outset; border-color: #ffffff #808080 #808080 #ffffff; font-family: 'MS Sans Serif', Tahoma, sans-serif; background: #c0c0c0 !important; color: #000 !important; }
button:active { border-style: inset; border-color: #808080 #ffffff #ffffff #808080; }
